function deductProductsStockClient(products: any[], items: any[], dep: string): any[] {
  return products.map(p => {
    const itemsToDeduct = items.filter(it => String(it.productId) === String(p.id));
    if (itemsToDeduct.length > 0) {
      const clonedProduct = { ...p };
      for (const it of itemsToDeduct) {
        const qty = it.quantity || 1;
        const pinStock = clonedProduct.stockPinamar || 0;
        const mvdStock = clonedProduct.stockMontevideo || 0;
        let pinDeduct = 0;
        let mvdDeduct = 0;
        if (dep === "Montevideo") {
          if (mvdStock >= qty) mvdDeduct = qty;
          else { mvdDeduct = mvdStock; pinDeduct = qty - mvdStock; }
        } else {
          if (pinStock >= qty) pinDeduct = qty;
          else { pinDeduct = pinStock; mvdDeduct = qty - pinStock; }
        }
        clonedProduct.stockPinamar = Math.max(0, pinStock - pinDeduct);
        clonedProduct.stockMontevideo = Math.max(0, mvdStock - mvdDeduct);
        clonedProduct.stock = Math.max(0, (clonedProduct.stock || 0) - qty);
        if (it.variantId && clonedProduct.variants) {
          clonedProduct.variants = clonedProduct.variants.map((v: any) => {
            if (String(v.id) === String(it.variantId)) {
              const clonedV = { ...v };
              const vPinStock = clonedV.stockPinamar || 0;
              const vMvdStock = clonedV.stockMontevideo || 0;
              let vPinDeduct = 0;
              let vMvdDeduct = 0;
              if (dep === "Montevideo") {
                if (vMvdStock >= qty) vMvdDeduct = qty;
                else { vMvdDeduct = vMvdStock; vPinDeduct = qty - vMvdStock; }
              } else {
                if (vPinStock >= qty) vPinDeduct = qty;
                else { vPinDeduct = vPinStock; vMvdDeduct = qty - vPinStock; }
              }
              clonedV.stockPinamar = Math.max(0, vPinStock - vPinDeduct);
              clonedV.stockMontevideo = Math.max(0, vMvdStock - vMvdDeduct);
              clonedV.stock = Math.max(0, (clonedV.stock || 0) - qty);
              return clonedV;
            }
            return v;
          });
        }
      }
      return clonedProduct;
    }
    return p;
  });
}

async function fetchImagesAsBase64(urls: string[]): Promise<Record<string, string>> {
  const validUrls = Array.from(new Set(urls.filter(u => typeof u === "string" && u.trim().length > 0)));
  if (validUrls.length === 0) return {};
  try {
    const res = await fetch("/api/images-to-base64", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ urls: validUrls })
    });
    if (res.ok) {
      const data = await res.json();
      if (data.success && data.images) return data.images;
    }
  } catch (err) {
    console.warn("Could not fetch base64 images from server:", err);
  }
  return {};
}

