                {adminSection === "calculator_3d" && (
                  <Dashboard3DCalculator
                    authToken={authToken}
                    onNavigateSection={(sec) => navigateAdminSection(sec as any)}
                    onProductCreated={() => {
                      fetchStoreData(true);
                    }}
                  />
                )}

                {/* 11. PAYMENTS CONTROL CENTER PANEL */}
